def comb_sort(nums):
    if len(nums) <= 1:
        return nums

    gap = len(nums)
    sorted_flag = False

    while not sorted_flag:
        gap = max(1, gap // 1.3)  # Decreasing gap
        sorted_flag = True

        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]  # Swap
                sorted_flag = False

    return nums
```

